'use strict';
(()=>{const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};function picker({root,team,api,onSelect}){const panel=el('details');panel.className='learning-template-picker';panel.append(el('summary','Reuse a saved recurring task'));root.prepend(panel);let loaded=false;panel.ontoggle=async()=>{if(!panel.open||loaded)return;loaded=true;const body=el('div');panel.append(body);try{let rows=[];for(let offset=0;;offset+=500){const r=await api.db.from('work_task_templates').select('id,title,instructions,recurrence,recurrence_days,recurrence_weeks').eq('team_id',team).order('title').range(offset,offset+499);if(r.error)throw r.error;rows.push(...r.data);if(r.data.length<500)break;}const label=el('label','Find a saved task'),search=el('input');search.type='search';label.append(search);const list=el('div');list.className='learning-template-list';body.append(label,el('p','Recurring tasks assigned by team admins are saved here automatically. Reuse copies the instructions and repeat pattern. Choose new dates and recipients below.'),list);function draw(){list.replaceChildren();const matches=rows.filter(r=>(r.title+' '+r.instructions).toLowerCase().includes(search.value.toLowerCase()));for(const item of matches){const b=el('button',item.title+' · '+({daily:'Daily',weekly:'Weekly',biweekly:'Every 2 weeks',monthly:'Monthly',quarterly:'Every 3 months'}[item.recurrence]||item.recurrence));b.type='button';b.onclick=()=>{onSelect(item);panel.open=false;};list.append(b);}if(!matches.length)list.append(el('p',rows.length?'No saved tasks match your search.':'No saved recurring tasks yet. Assign a recurring task as a team admin to add it here.'));}search.oninput=draw;draw();}catch(e){loaded=false;body.textContent='Could not load saved tasks: '+e.message;}};return panel;}window.GuhuzaWorkTemplates={picker};})();
